<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';import {useMatches,useSlip} from '../stores/store';import {heroSlides,fmtTime} from '../data/mock';import LandingHero from '../components/LandingHero.vue';const ms:any=useMatches(),slip=useSlip();const tab=ref('highlights');const market=ref('1X2');const league=ref('All');const showFilters=ref(false);const liveOnly=ref(false);const todayOnly=ref(false);const liveIdx=Math.max(0,heroSlides.findIndex((x:any)=>x.enTitle==='Live Betting'));const slide=ref(liveIdx);const reducedMotion=ref(false);const isLiveSlide=computed(()=>heroSlides[slide.value]?.enTitle==='Live Betting');let t:any,s:any;onMounted(()=>{ms.load();reducedMotion.value=window.matchMedia('(prefers-reduced-motion: reduce)').matches;t=setInterval(()=>ms.tick(),4000);const adv=()=>{slide.value=(slide.value+1)%heroSlides.length;s=setTimeout(adv,slide.value===liveIdx?10000:4500)};s=setTimeout(adv,10000)});onUnmounted(()=>{clearInterval(t);clearTimeout(s)});
function displayOdds(m:any){ if(market.value==='OU') return m.markets?.['Over/Under'] ?? []; if(market.value==='BTTS') return m.markets?.BTTS ?? []; return m.odds ?? [] }
const list=computed(()=>ms.list.filter((m:any)=>(ms.selectedSport==='All'||m.sport===ms.selectedSport)&&(league.value==='All'||m.league===league.value)&&(tab.value==='live'?m.live:tab.value==='upcoming'?!m.live:true)&&(!liveOnly.value||m.live)&&(!todayOnly.value||new Date(m.kickoff).toDateString()===new Date().toDateString())));
const groups=computed(()=>{const g:Record<string,any[]>={};list.value.forEach((m:any)=>{const k=m.league+' • '+m.country;(g[k]=g[k]||[]).push(m)});return g});
const countries=computed<string[]>(()=>[...new Set<string>(ms.list.map((m:any)=>String(m.country)))]);
const leagues=computed<string[]>(()=>[...new Set<string>(ms.list.map((m:any)=>String(m.league)).filter(Boolean))]);
</script>
<template><LandingHero/>
<h2>{{$t('home')}} <span v-if="ms.selectedSport!=='All'">— {{ms.selectedSport}} <button @click="ms.setSport('All')">×</button></span></h2>
<div class="chips"><button :class="{active:tab==='highlights'}" @click="tab='highlights'">Highlights</button><button :class="{active:tab==='live'}" @click="tab='live'">{{$t('live')}}</button><button :class="{active:tab==='upcoming'}" @click="tab='upcoming'">{{$t('upcoming')}}</button><button @click="showFilters=!showFilters">Filters</button><button :class="{active:todayOnly}" @click="todayOnly=!todayOnly">Today</button><label>Market <select v-model="market"><option>1X2</option><option value="OU">Over/Under 2.5</option><option value="BTTS">BTTS</option></select></label></div>
<div class="chips" data-testid="league-filters"><button type="button" :class="{active:league==='All'}" @click="league='All'">{{$t('all')}}</button><button v-for="name in leagues" :key="name" type="button" :class="{active:league===name}" @click="league=name">{{name}}</button></div>
<div v-if="showFilters" class="card"><label><input type="checkbox" v-model="liveOnly"/> Live only</label> <label>Sport: <select :value="ms.selectedSport" @change="ms.setSport(($event.target as any).value)"><option>All</option><option>Football</option><option>Basketball</option><option>Tennis</option><option>Cricket</option><option>Volleyball</option><option>eSoccer</option><option>Counter-Strike</option></select></label></div>
<div class="card"><b>Countries:</b> <span v-for="c in countries" :key="c"> {{c}} · </span> <RouterLink to="/livescore">Livescore →</RouterLink></div>
<div data-testid="sports-list"><div v-for="(items,name) in groups" :key="name"><h3>{{name}}</h3><div class="match" v-for="m in items" :key="m.id"><RouterLink :to="`/match/${m.id}`"><b>{{m.home}} vs {{m.away}}</b><br/><small>{{fmtTime(m.kickoff)}} EAT <span v-if="m.live" class="live">LIVE {{m.minute}}' {{m.hs}}-{{m.as}}</span></small></RouterLink><div class="odds"><button v-for="o in displayOdds(m)" :key="o.oddsId || o.sel" type="button" @click="slip.toggle(m,o)">{{o.sel}}<b>{{Number(o.price).toFixed(2)}}</b></button></div><RouterLink :to="`/match/${m.id}`">+{{m.marketsCount}} Markets</RouterLink></div></div></div>
<p v-if="ms.loaded && !list.length">{{$t('noMatches')}}</p></template>
